import{_ as a,o as t,c as o,aw as r}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Установка и настройка","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react-native/main/install.md","filePath":"wiki/dev-commit/framework-react/react-native/main/install.md"}'),i={name:"wiki/dev-commit/framework-react/react-native/main/install.md"};function p(l,e,c,n,s,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="установка-и-настроика" tabindex="-1">Установка и настройка <a class="header-anchor" href="#установка-и-настроика" aria-label="Permalink to &quot;Установка и настройка&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://reactnative.dev/docs/environment-setup" target="_blank" rel="noreferrer">https://reactnative.dev/docs/environment-setup</a></p></div><ol><li>Expo Go Quickstart - это набор инструментов и сервисов, построенных на основе React Native (не нужно настраивать)</li><li>React Native CLI Quickstart - работает с Xcode или Android Studio (нужно настраивать)</li></ol><h2 id="_1-expo-go-quickstart" tabindex="-1">1. Expo Go Quickstart <a class="header-anchor" href="#_1-expo-go-quickstart" aria-label="Permalink to &quot;1. Expo Go Quickstart&quot;">​</a></h2><h4 id="_1-установить-приложениеexpo-goна-телефон" tabindex="-1">1. Установить приложениеExpo Goна телефон <a class="header-anchor" href="#_1-установить-приложениеexpo-goна-телефон" aria-label="Permalink to &quot;1. Установить приложениеExpo Goна телефон&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://expo.dev/client" target="_blank" rel="noreferrer">https://expo.dev/client</a><a href="https://docs.expo.dev/" target="_blank" rel="noreferrer">https://docs.expo.dev/</a></p></div><ul><li><p><strong>Expo</strong> - фреймворк над React Native (набор инструментов и сервисов, построенных на основе React Native)</p></li><li><p>Установить приложение Expo Go на телефон <a href="https://expo.dev/client" target="_blank" rel="noreferrer">https://expo.dev/client</a></p></li><li><p>Подключиться к той же беспроводной сети, что и компьютер</p></li><li><p>На Android используйте приложение Expo Go, чтобы отсканировать QR-код с вашего терминала, чтобы открыть свой проект. В iOS используйте встроенный сканер QR-кода стандартного приложения iOS Camera</p></li></ul><h4 id="_2-установить-expo-cli" tabindex="-1">2. Установить Expo CLI <a class="header-anchor" href="#_2-установить-expo-cli" aria-label="Permalink to &quot;2. Установить Expo CLI&quot;">​</a></h4><p>npm i -g expo-cli npx expo install</p><h4 id="_3-установить-проект-черезcreate-expo-app" tabindex="-1">3. Установить проект черезcreate-expo-app <a class="header-anchor" href="#_3-установить-проект-черезcreate-expo-app" aria-label="Permalink to &quot;3. Установить проект черезcreate-expo-app&quot;">​</a></h4><p>npx create-expo-app AwesomeProject</p><h4 id="_4-запустить-проект-в-приложенииexpo-go" tabindex="-1">4. Запустить проект в приложенииExpo Go <a class="header-anchor" href="#_4-запустить-проект-в-приложенииexpo-go" aria-label="Permalink to &quot;4. Запустить проект в приложенииExpo Go&quot;">​</a></h4><p>cd AwesomeProject npm start</p><ul><li>После старта проекта появится QR-код, который нужно отсканировать в приложении Expo Go (Android) / Camera app (iOS)</li><li>После этого, проект запустится в приложении на телефоне</li></ul>',14)])])}const m=a(i,[["render",p]]);export{h as __pageData,m as default};
